import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Implement the Chain of Responsibility pattern.
 *
 * Support tickets carry a severity from 1 to 5. Each handler deals with a ticket only
 * when the severity is at or below its own limit; otherwise it passes the ticket along
 * to the next handler in the chain.
 *
 * Complete SupportEscalation:
 *   LevelHandler.setNext(next) -- links this handler to the next one and returns next,
 *                                 so a chain can be built with repeated calls
 *   LevelHandler.handle(sev)   -- "<name> handled level <sev>" when this handler can take it,
 *                                 otherwise the next handler's answer, or "unresolved"
 *                                 when there is no next handler
 *   buildDefaultChain()        -- the HEAD of the chain bot(1) -> agent(3) -> manager(4)
 *   routeAll(severities)       -- each severity sent through a fresh default chain
 *
 * Example: buildDefaultChain().handle(3) -> "agent handled level 3"
 *          buildDefaultChain().handle(5) -> "unresolved"
 */
interface TicketHandler {

    String handle(int severity);
}

public class SupportEscalation {

    public static class LevelHandler implements TicketHandler {

        private final String name;
        private final int limit;
        private TicketHandler next;

        public LevelHandler(String name, int limit) {
            this.name = name;
            this.limit = limit;
        }

        public LevelHandler setNext(LevelHandler next) {
