public class SupportEscalationTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String route(int severity) {
        try {
            SupportEscalation.LevelHandler head = SupportEscalation.buildDefaultChain();
            if (head == null) {
                return "chain was null";
            }
            return head.handle(severity);
        } catch (RuntimeException e) {
            return e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("severity 1 stops at the bot", "bot handled level 1", route(1));
        check("severity 2 reaches the agent", "agent handled level 2", route(2));
        check("severity 3 still fits the agent", "agent handled level 3", route(3));
        check("severity 4 reaches the manager", "manager handled level 4", route(4));
        check("severity 5 falls off the end", "unresolved", route(5));

        try {
            check("routeAll results", "[bot handled level 1, manager handled level 4, unresolved]",
                  String.valueOf(SupportEscalation.routeAll(new int[]{1, 4, 5})));
        } catch (RuntimeException e) {
            check("routeAll results", "[bot handled level 1, manager handled level 4, unresolved]",
                  e.getClass().getSimpleName());
        }

        SupportEscalation.LevelHandler lone = new SupportEscalation.LevelHandler("intern", 2);
        check("a single handler takes what it can", "intern handled level 2", lone.handle(2));
        check("a single handler with nobody to pass to", "unresolved", lone.handle(3));

        SupportEscalation.LevelHandler first = new SupportEscalation.LevelHandler("first", 1);
        SupportEscalation.LevelHandler second = new SupportEscalation.LevelHandler("second", 9);
        check("setNext returns the handler it was given", true, first.setNext(second) == second);
        check("the new link is used", "second handled level 7", first.handle(7));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

