import java.util.ArrayList;
import java.util.List;

interface TicketHandler {

    String handle(int severity);
}

public class SupportEscalation {

    public static class LevelHandler implements TicketHandler {

        private final String name;
        private final int limit;
        private TicketHandler next;

        public LevelHandler(String name, int limit) {
            this.name = name;
            this.limit = limit;
        }

        public LevelHandler setNext(LevelHandler next) {
            this.next = next;
            return next;
        }

        @Override
        public String handle(int severity) {
            if (severity <= limit) {
                return name + " handled level " + severity;
            }
            if (next == null) {
                return "unresolved";
            }
            return next.handle(severity);
        }
    }

    public static LevelHandler buildDefaultChain() {
        LevelHandler bot = new LevelHandler("bot", 1);
        LevelHandler agent = new LevelHandler("agent", 3);
        LevelHandler manager = new LevelHandler("manager", 4);
        bot.setNext(agent).setNext(manager);
        return bot;
    }

    public static List<String> routeAll(int[] severities) {
        List<String> results = new ArrayList<>();
        for (int severity : severities) {
            results.add(buildDefaultChain().handle(severity));
        }
        return results;
    }
}
